INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31669$nota-0243$m31669$, $m31670$Exercise Physiology McArdle.pdf$m31670$, $m31671$491$m31671$, $m31672$Overload: A planned, systematic, and progressive increase in training to improve performance. Overreaching: Unplanned, excessive overload with inadequate rest. Poor performance is observed in training and competition. Successful recovery should result from short-term (i.e., a few days up to 1 or 2 wk) interventions. Overtraining syndrome: Untreated overreaching that produces long-term decreased performance and impaired ability to train.$m31672$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31673$nota-0243$m31673$, $m31674$Exercise Physiology McArdle.pdf$m31674$, $m31675$491$m31675$, $m31676$Two clinical forms of overtraining have been described: 1. The less common sympathetic form (basedowian for thyroid hyperfunction patterns), characterized by increased sympathetic activity during rest... 2. The more common parasympathetic form (addisonoid for adrenal insufficiency patterns), characterized by predominance of vagal activity during rest and physical activity. More properly termed overreaching in the early stages (within as few as 10 days)...$m31676$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31677$nota-0243$m31677$, $m31678$Exercise Physiology McArdle.pdf$m31678$, $m31679$490$m31679$, $m31680$Ten to 20% of athletes experience overtraining or 'staleness.'$m31680$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31681$nota-0243$m31681$, $m31682$nota-0148$m31682$, $m31683$complementa$m31683$, $m31684$nota-0148 distingue overreached/overtrained apenas pelo critério de duração de recuperação (Training and Racing with a Power Meter); esta nota adiciona um terceiro degrau (Overload, planejado) e a distinção por forma clínica (simpática vs. parassimpática), refinando a mesma linha do tempo$m31684$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31685$nota-0243$m31685$, $m31686$nota-0092$m31686$, $m31687$complementa$m31687$, $m31688$fornece o contexto clínico/sintomático por trás do overreaching não funcional descrito na nota-0092$m31688$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31689$nota-0244$m31689$, $m31690$Exercise Physiology McArdle.pdf$m31690$, $m31691$491$m31691$, $m31692$Figure 21.24 illustrates possible interactive factors that initiate parasympathetic-type overtraining syndrome. Interactions among chronic neuromuscular, neuroendocrine, psychologic, immunologic, and metabolic overload during long-term, high-volume training (with insufficient recuperation) eventually alter physiologic function and the stress response to produce the overtrained state.$m31692$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31693$nota-0244$m31693$, $m31694$Exercise Physiology McArdle.pdf$m31694$, $m31695$492$m31695$, $m31696$Figure 21.24 Schematic overview of the genesis of overtraining syndrome in endurance sports requiring prolonged high-volume training. (Adapted with permission from Lehmann M, et al. Autonomic imbalance hypothesis and overtraining syndrome. Med Sci Sports Exerc 1998;30:1140.)$m31696$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31697$nota-0244$m31697$, $m31698$Exercise Physiology McArdle.pdf$m31698$, $m31699$491$m31699$, $m31700$Significant effects of a chronic imbalance of training load, competition, and nontraining stress factors in overtraining include the following: 1. Functional impairments in the hypothalamo-pituitary-gonadal and adrenal axes and sympathetic neuroendocrine system reflected by depressed urinary excretion of norepinephrine and a desensitization of the β2-adrenergic system. 2. Exercise-induced increases in adrenocorticotropic hormone and growth hormone and decreases in cortisol and insulin levels.$m31700$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31701$nota-0244$m31701$, $m31702$nota-0243$m31702$, $m31703$complementa$m31703$, $m31704$nota-0243 descreve a terminologia e as duas formas clínicas de overtraining; esta nota detalha o modelo mecanístico (Lehmann 1998) que explica como a sobrecarga crônica gera a síndrome$m31704$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31705$nota-0244$m31705$, $m31706$nota-0195$m31706$, $m31707$complementa$m31707$, $m31708$o modelo de Lehmann situa a fadiga central e periférica (nota-0195) como duas das vias de saída do mesmo processo de desequilíbrio crônico (via neuromuscular → fadiga periférica; via psicológica/neuroendócrina → fadiga central)$m31708$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31709$nota-0244$m31709$, $m31710$nota-0092$m31710$, $m31711$complementa$m31711$, $m31712$fornece o mecanismo hipotético por trás do overreaching não funcional descrito na nota-0092$m31712$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31713$nota-0244$m31713$, $m31714$nota-0193$m31714$, $m31715$complementa$m31715$, $m31716$citada no corpo da nota ('Nota sobre o cânone') como a lacuna de métrica quantitativa (Monotonia/Strain de Foster) que este modelo qualitativo não resolve — link estrutural ausente até auditoria de 2026-08-02$m31716$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31717$nota-0287$m31717$, $m31718$Exercise Physiology McArdle.pdf$m31718$, $m31719$823$m31719$, $m31720$A bout of vigorous physical activity may increase recovery oxygen consumption for up to 14 hr. Ten young adult men bicycled for 45 min at a vigorous pace equivalent to 73% VO2max. Energy expenditure was then measured for 24 hr while the men recovered in a metabolic chamber.$m31720$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31721$nota-0287$m31721$, $m31722$Exercise Physiology McArdle.pdf$m31722$, $m31723$823$m31723$, $m31724$In the 14-hr period following cycling, the men burned 190 more calories than on a day when they remained sedentary. This 37% recovery calorie-burning bonus occurred in addition to the 520 calories burned during cycling.$m31724$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m31725$nota-0287$m31725$, $m31726$nota-0232$m31726$, $m31727$complementa$m31727$, $m31728$nota-0232 descreve o EPOC (componentes rápido e lento) de forma geral; esta nota traz um dado quantitativo específico de uma sessão de ciclismo vigoroso (73% VO2máx, 45min) medido em câmara metabólica por 14h$m31728$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31729$nota-0006$m31729$, $m31730$Training and Racing with a Power Meter.pdf$m31730$, $m31731$30$m31731$, $m31732$On an indoor trainer, without the outside influences of wind, hills, dogs, and so on, you can focus your intervals in exact wattage zones for optimal improvement.$m31732$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31733$nota-0006$m31733$, $m31734$Training and Racing with a Power Meter.pdf$m31734$, $m31735$31$m31735$, $m31736$Power-meter data from indoor training sessions are also \"cleaner\" than from on-road efforts, as the massive wattage fluctuations caused by changes in terrain, riding with others, and just the variable nature of pedaling frequency are gone from the power file.$m31736$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m31737$nota-0007$m31737$, $m31738$Training and Racing with a Power Meter.pdf$m31738$, $m31739$24$m31739$, $m31740$whenever this racer's cadence dropped below 70 rpm for more than five minutes while riding at his threshold power output, he was dropped. However, Hunter also found many cases in which the cyclist was able to stay with the same athletes at and above his threshold wattage as long as his cadence was over 95 rpm.$m31740$);
